 return head('System settings','AUDIT / LANGUAGE / DATA')+'<div class="grid two">'+panel('Language for floor screens',languages)+panel('Local prototype data',local)+formStart('purchase-order','Create supplier PO from a shortfall',poFields,'CREATE PURCHASE ORDER')+panel('Audit log',table(['TIME','ROLE','ACTION','DETAIL'],logs,'Changes are recorded as they happen.'))+'</div>';
